<?php declare(strict_types=1); namespace Annam; $title=($id?'Edit ':'Add ').strtolower($spec['title']); ?>
<a class="o-crumb" href="/manage/<?= e($key) ?>/">← <?= e($spec['title']) ?></a><form method="post" enctype="multipart/form-data" class="o-form"><?= csrf() ?><section class="o-card"><div class="o-grid-form">
<?php foreach ($spec['fields'] as $field=>$definition): [$label,$type]=explode('|',$definition); $value=$record[$field]??''; ?>
<?php if ($type==='bool'): ?><label class="o-check"><input type="checkbox" name="<?= e($field) ?>" value="1" <?= $value?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span class="o-toggle-copy"><b><?= e($label) ?></b></span></label>
<?php elseif ($type==='slots'): $values=is_string($value)?json_decode($value,true):[]; ?><fieldset class="php-fieldset"><legend><?= e($label) ?></legend><?php foreach (['breakfast','lunch','dinner','snacks'] as $meal): ?><label class="o-check"><input type="checkbox" name="slot_keys[]" value="<?= e($meal) ?>" <?= in_array($meal,$values?:[],true)?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span><?= e(ucfirst($meal)) ?></span></label><?php endforeach; ?><small>Select each meal this area serves.</small></fieldset>
<?php else: ?><label class="o-field"><span><?= e($label) ?></span>
<?php if ($type==='textarea'): ?><textarea name="<?= e($field) ?>" rows="5"><?= e($value) ?></textarea>
<?php elseif ($type==='fulfilment'): ?><select name="<?= e($field) ?>"><option value="scheduled" <?= $value==='scheduled'?'selected':'' ?>>Meals</option><option value="courier" <?= $value==='courier'?'selected':'' ?>>Other items</option></select>
<?php elseif ($type==='category'): ?><select name="category_id"><option value="">No category</option><?php foreach ($store->categories() as $cat): ?><option value="<?= e($cat['id']) ?>" <?= (string)$value===(string)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select>
<?php else: ?><input name="<?= e($field) ?>" value="<?= e($value) ?>" type="<?= in_array($type,['time','optional_time'],true)?'time':(in_array($type,['price','int'],true)?'number':'text') ?>" <?= $type==='price'?'min="0" step="0.01"':($type==='int'?'min="0" step="1"':'') ?> <?= in_array($type,['text','price','time','slug','pincode'],true)?'required':'' ?>><?php endif; ?></label><?php endif; ?>
<?php endforeach; ?>
<?php if (array_key_exists('image',$spec['defaults'])): ?><label class="o-field"><span>Photo</span><?php if (!empty($record['image'])): ?><img class="php-edit-image" src="<?= e(image_url($record['image'])) ?>" alt="Current photo"><?php endif; ?><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · up to 3 MB. Leave blank to keep the current photo.</small></label><?php endif; ?></div></section><div class="o-form-bar"><a class="o-btn" href="/manage/<?= e($key) ?>/">Cancel</a><button class="o-btn o-btn-primary" type="submit">Save changes →</button></div></form>
